class Solution { public int[] rearrangeBarcodes(int[] barcodes){Map<Integer,Integer> count=new HashMap<>();for(int value:barcodes)count.merge(value,1,Integer::sum);PriorityQueue<int[]> heap=new PriorityQueue<>((a,b)->a[0]!=b[0]?b[0]-a[0]:a[1]-b[1]);for(Map.Entry<Integer,Integer> entry:count.entrySet())heap.offer(new int[]{entry.getValue(),entry.getKey()});int[] answer=new int[barcodes.length],previous=null;for(int i=0;i<answer.length;i++){int[] current=heap.poll();answer[i]=current[1];current[0]--;if(previous!=null&&previous[0]>0)heap.offer(previous);previous=current;}return answer;} }
